// Plan -> confirm -> deploy -> wait, shared by the "new app" page and the
// app detail page (where the same flow changes an existing app).
//
// After /api/apply the Fleet bundle is polled through Steve; once it is
// ready (or only "modified"), each Deployment from the apply response must
// run the committed pod template before the app link is offered
// (utils/rollout.ts).
import {
  ref, computed, onBeforeUnmount, Ref, ComputedRef
} from 'vue';
import {
  getConfig, createPlan, applyPlan, restoreVersion, listBundles, getDeployment, resolveAppUrl, safeHttpsUrl,
  aiRequestTimeoutMs, RequestError, ConfigResponse, PlanResponse, ApplyResponse, StoreLike
} from '../utils/backend';
import { bundleReadiness, Readiness } from '../utils/bundle';
import { deploymentRolledOut, rolloutTargets } from '../utils/rollout';
import { BUNDLE_POLL_INTERVAL_MS, BUNDLE_POLL_TIMEOUT_MS, FLEET_WORKSPACE } from '../config/backend';

// Without a visible Fleet bundle for this long, the Deployments decide.
const DEPLOYMENTS_AFTER_MS = 60 * 1000;

import { TRANSLATED_ERRORS } from '../utils/errors';

export type Phase = 'idle' | 'planning' | 'planned' | 'applying' | 'deploying' | 'ready' | 'timeout';

type Translate = (key: string, args?: Record<string, unknown>) => string;

export interface DeployFlowHooks {
  // After a successful /api/apply (the commit exists).
  onApplied?: (applied: ApplyResponse) => void;
  // When the new version is running (or Fleet stopped at "modified").
  onReady?: (applied: ApplyResponse) => void;
  // A request failed; lets the lock notice "locked"/"lock_required".
  onError?: (e: unknown) => void;
}

// A change published without AI: restore, hand-edited code, 3D layout.
export type DirectKind = 'restore' | 'manual' | 'layout' | 'round';

export interface DeployFlow {
  config: Ref<ConfigResponse | null>;
  configError: Ref<string>;
  phase: Ref<Phase>;
  errorText: Ref<string>;
  plan: Ref<PlanResponse | null>;
  applied: Ref<ApplyResponse | null>;
  readiness: Ref<Readiness | null>;
  pollError: Ref<boolean>;
  rollingOut: Ref<boolean>;
  elapsed: Ref<number>;
  busy: ComputedRef<boolean>;
  canApply: ComputedRef<boolean>;
  steps: ComputedRef<string[]>;
  commitLink: ComputedRef<string | null>;
  shortCommit: ComputedRef<string>;
  appLink: ComputedRef<string | null>;
  statusText: ComputedRef<string>;
  showStatusMessage: ComputedRef<boolean>;
  loadConfig: () => Promise<void>;
  generatePlan: (prompt: string, opts?: { appName?: string; baseApp?: string }) => Promise<void>;
  confirmAndDeploy: () => Promise<void>;
  restore: (app: string, commit: string) => Promise<void>;
  // Publish a change made without AI and wait for it like an apply.
  // Resolves true once the commit exists.
  publishDirect: (kind: DirectKind, call: (timeoutMs: number) => Promise<ApplyResponse>) => Promise<boolean>;
  // True while the current deploy is a restore (no AI involved).
  restoring: ComputedRef<boolean>;
  // The kind of the current no-AI change, if any.
  directKind: Ref<DirectKind | null>;
  // Wait for a change published elsewhere (a round finished by this or
  // another user) like an apply.
  watchApplied: (applied: ApplyResponse) => void;
  reset: () => void;
  messageFor: (e: unknown) => string;
}

export function useDeployFlow(store: StoreLike, t: Translate, hooks: DeployFlowHooks = {}): DeployFlow {
  const config = ref<ConfigResponse | null>(null);
  const configError = ref('');
  const phase = ref<Phase>('idle');
  const errorText = ref('');
  const plan = ref<PlanResponse | null>(null);
  const applied = ref<ApplyResponse | null>(null);
  const readiness = ref<Readiness | null>(null);
  const pollError = ref(false);
  const rollingOut = ref(false);
  const elapsed = ref(0);
  const directKind = ref<DirectKind | null>(null);
  const restoring = computed(() => directKind.value === 'restore');

  let elapsedTimer: ReturnType<typeof setInterval> | null = null;
  let pollTimer: ReturnType<typeof setTimeout> | null = null;
  let pollStarted = 0;
  let pollGeneration = 0;
  let unmounted = false;

  const busy = computed(() => phase.value === 'planning' || phase.value === 'applying');
  // The plan expired or was already used (report 24, N30): it cannot be
  // deployed any more; a new one has to be generated.
  const planGone = ref(false);
  const canApply = computed(() => !busy.value && !!plan.value && !applied.value && !planGone.value);
  const steps = computed(() => {
    const list = plan.value?.steps;

    return Array.isArray(list) ? list.map((s) => String(s)) : [];
  });
  const commitLink = computed(() => safeHttpsUrl(applied.value?.commitUrl));
  const shortCommit = computed(() => String(applied.value?.commit || '').slice(0, 12));
  const appLink = computed(() => resolveAppUrl(applied.value?.appUrl, window.location.origin));

  function fail(e: unknown): string {
    hooks.onError?.(e);

    return messageFor(e);
  }

  function messageFor(e: unknown): string {
    // Codes with a message in the UI language.
    if (e instanceof RequestError && e.code === 'not_editable') {
      return t('laoban.apps.legacy');
    }
    // The backend writes its messages in Chinese: these common ones are
    // shown in the page's language instead (report 21, N8).
    if (e instanceof RequestError && TRANSLATED_ERRORS.includes(e.code)) {
      return t(`laoban.errors.${ e.code }`);
    }
    if (e instanceof RequestError && e.userMessage) {
      return e.userMessage;
    }
    if (e instanceof RequestError && e.code === 'timeout') {
      return t('laoban.dashboard.errors.timeout');
    }

    return t('laoban.dashboard.errors.generic');
  }

  function stopElapsed() {
    if (elapsedTimer) {
      clearInterval(elapsedTimer);
      elapsedTimer = null;
    }
  }

  function startElapsed() {
    stopElapsed();
    elapsed.value = 0;
    const start = Date.now();

    elapsedTimer = setInterval(() => {
      elapsed.value = Math.floor((Date.now() - start) / 1000);
    }, 1000);
  }

  function stopPolling() {
    pollGeneration++;
    if (pollTimer) {
      clearTimeout(pollTimer);
      pollTimer = null;
    }
  }

  async function loadConfig() {
    try {
      config.value = await getConfig(store);
      configError.value = '';
    } catch (e) {
      configError.value = messageFor(e);
    }
  }

  // True when every Deployment from the apply response runs the new template.
  async function rolledOut(gen: number): Promise<boolean | null> {
    const targets = rolloutTargets(applied.value?.rollout);

    try {
      for (const target of targets) {
        const d = await getDeployment(store, target.path);

        if (gen !== pollGeneration) {
          return null;
        }
        // Read fine: an earlier failed poll is over.
        pollError.value = false;
        if (!deploymentRolledOut(d, target.contentHash)) {
          return false;
        }
      }
      pollError.value = false;
    } catch (e) {
      if (gen !== pollGeneration) {
        return null;
      }
      pollError.value = true;

      return false;
    }

    return true;
  }

  // The caller cannot read Fleet's bundles (see poll); reset per deploy.
  let bundlesHidden = false;
  // Waiting on the Deployments alone (shown in the status line).
  const deploymentsOnly = ref(false);

  async function poll(gen: number) {
    if (unmounted || gen !== pollGeneration || !applied.value) {
      return;
    }
    try {
      const bundles = await listBundles(store);

      if (gen !== pollGeneration) {
        return;
      }
      readiness.value = bundleReadiness(bundles, applied.value.fleet?.bundlePrefix || '', applied.value.commit);
      pollError.value = false;
    } catch (e) {
      if (gen !== pollGeneration) {
        return;
      }
      // Fleet's bundles live in the local cluster's fleet-default namespace,
      // which project members usually cannot read. Without them, the
      // Deployments in the app's own namespace (readable with the laoban
      // user role) tell when the new version runs.
      if (e instanceof RequestError && e.status === 403) {
        bundlesHidden = true;
      } else {
        pollError.value = true;
      }
    }

    // 'modified': running but drifted from Git; offer the app anyway.
    // Also when the bundle stays out of sight (an empty list for a caller
    // who may list bundles elsewhere, or Fleet being slow): after a while
    // the Deployments decide, as above.
    const unseen = !readiness.value || readiness.value.state === 'missing';
    const viaDeployments = rolloutTargets(applied.value?.rollout).length > 0 &&
      (bundlesHidden || (unseen && Date.now() - pollStarted >= DEPLOYMENTS_AFTER_MS));

    deploymentsOnly.value = viaDeployments && unseen;

    // 'pending' at the new commit: Fleet can stay "0 / 1 ready" for minutes
    // while an old pod terminates (report 26 N40). The new version may
    // already run; the Deployments tell.
    const atNewCommit = readiness.value?.state === 'pending';

    if (viaDeployments || atNewCommit || readiness.value?.state === 'ready' || readiness.value?.state === 'modified') {
      const done = await rolledOut(gen);

      if (done === null) {
        return;
      }
      rollingOut.value = !done;
      if (done) {
        phase.value = 'ready';
        stopElapsed();
        if (applied.value) {
          hooks.onReady?.(applied.value);
        }

        return;
      }
    }
    if (Date.now() - pollStarted >= BUNDLE_POLL_TIMEOUT_MS) {
      phase.value = 'timeout';
      stopElapsed();

      return;
    }
    pollTimer = setTimeout(() => poll(gen), BUNDLE_POLL_INTERVAL_MS);
  }

  function startPolling() {
    stopPolling();
    readiness.value = null;
    rollingOut.value = false;
    pollError.value = false;
    bundlesHidden = false;
    deploymentsOnly.value = false;
    pollStarted = Date.now();
    phase.value = 'deploying';
    startElapsed();
    poll(pollGeneration);
  }

  function reset() {
    directKind.value = null;
    stopPolling();
    stopElapsed();
    errorText.value = '';
    plan.value = null;
    planGone.value = false;
    applied.value = null;
    readiness.value = null;
    rollingOut.value = false;
    pollError.value = false;
    phase.value = 'idle';
  }

  async function generatePlan(prompt: string, opts: { appName?: string; baseApp?: string } = {}) {
    if (busy.value || !prompt.trim()) {
      return;
    }
    reset();
    phase.value = 'planning';
    planGone.value = false;
    startElapsed();
    try {
      plan.value = await createPlan(store, prompt.trim(), opts.appName || undefined, aiRequestTimeoutMs(config.value), opts.baseApp);
      phase.value = 'planned';
    } catch (e) {
      errorText.value = fail(e);
      phase.value = 'idle';
    } finally {
      stopElapsed();
      loadConfig();
    }
  }

  async function confirmAndDeploy() {
    if (!canApply.value || !plan.value) {
      return;
    }
    errorText.value = '';
    phase.value = 'applying';
    startElapsed();
    try {
      applied.value = await applyPlan(store, plan.value.planId, aiRequestTimeoutMs(config.value));
    } catch (e) {
      errorText.value = fail(e);
      planGone.value = e instanceof RequestError && (e.code === 'plan_not_found' || e.code === 'already_applied');
      phase.value = 'planned';
      stopElapsed();

      return;
    } finally {
      loadConfig();
    }
    hooks.onApplied?.(applied.value);
    startPolling();
  }

  async function publishDirect(kind: DirectKind, call: (timeoutMs: number) => Promise<ApplyResponse>): Promise<boolean> {
    if (busy.value) {
      return false;
    }
    reset();
    directKind.value = kind;
    phase.value = 'applying';
    startElapsed();
    try {
      // No AI call, but a GitHub commit: same timeout as an apply.
      applied.value = await call(aiRequestTimeoutMs(config.value));
    } catch (e) {
      errorText.value = fail(e);
      phase.value = 'idle';
      directKind.value = null;
      stopElapsed();

      return false;
    }
    hooks.onApplied?.(applied.value);
    startPolling();

    return true;
  }

  function watchApplied(result: ApplyResponse) {
    if (applied.value?.commit === result.commit) {
      return;
    }
    reset();
    directKind.value = 'round';
    applied.value = result;
    hooks.onApplied?.(result);
    startPolling();
  }

  // An earlier version published again: same deploy and wait as an apply.
  async function restore(app: string, commit: string) {
    await publishDirect('restore', (timeoutMs) => restoreVersion(store, app, commit, timeoutMs));
  }

  const statusText = computed(() => {
    switch (phase.value) {
    case 'planning':
      return t('laoban.dashboard.status.planning', { seconds: elapsed.value });
    case 'planned':
      return planGone.value ? t('laoban.dashboard.status.planGone') : t('laoban.dashboard.status.planned');
    case 'applying':
      if (directKind.value === 'restore') {
        return t('laoban.versions.restoring', { seconds: elapsed.value });
      }
      if (directKind.value) {
        return t('laoban.editor.saving', { seconds: elapsed.value });
      }

      return t('laoban.dashboard.status.applying', { seconds: elapsed.value });
    case 'deploying': {
      const r = readiness.value;

      if (deploymentsOnly.value) {
        return t('laoban.dashboard.status.waitingPods', { seconds: elapsed.value });
      }
      if (!r || r.state === 'missing') {
        return t('laoban.dashboard.status.waitingBundle', { seconds: elapsed.value });
      }
      if (r.state === 'error') {
        return t('laoban.dashboard.status.bundleError', { ready: r.ready, desired: r.desired });
      }
      if (rollingOut.value) {
        return t('laoban.dashboard.status.rollingOut', { seconds: elapsed.value });
      }

      return t('laoban.dashboard.status.deploying', { ready: r.ready, desired: r.desired });
    }
    case 'ready':
      return readiness.value?.state === 'modified' ? t('laoban.dashboard.status.readyModified', { workspace: FLEET_WORKSPACE }) : t('laoban.dashboard.status.ready');
    case 'timeout':
      return t('laoban.dashboard.status.timeout', { minutes: Math.round(BUNDLE_POLL_TIMEOUT_MS / 60000), workspace: FLEET_WORKSPACE });
    default:
      return t('laoban.dashboard.status.idle');
    }
  });

  // Fleet's own message is shown next to the status while deploying, and
  // after "ready" when Fleet stopped at "modified".
  const showStatusMessage = computed(() => !!readiness.value?.message &&
    (phase.value === 'deploying' || (phase.value === 'ready' && readiness.value?.state === 'modified')));

  // Settings such as the token cap change with a helm upgrade while the
  // page stays open: read them again when the user comes back to the tab
  // (report 24, N31).
  function onFocus() {
    if (!busy.value) {
      loadConfig();
    }
  }

  if (typeof window !== 'undefined') {
    window.addEventListener('focus', onFocus);
  }

  onBeforeUnmount(() => {
    unmounted = true;
    stopPolling();
    stopElapsed();
    if (typeof window !== 'undefined') {
      window.removeEventListener('focus', onFocus);
    }
  });

  return {
    config,
    configError,
    phase,
    errorText,
    plan,
    applied,
    readiness,
    pollError,
    rollingOut,
    elapsed,
    busy,
    canApply,
    steps,
    commitLink,
    shortCommit,
    appLink,
    statusText,
    showStatusMessage,
    loadConfig,
    generatePlan,
    confirmAndDeploy,
    restore,
    publishDirect,
    restoring,
    directKind,
    watchApplied,
    reset,
    messageFor,
  };
}
